import pyomo.environ as pyo

DATA = {
    "warehouses": [1, 2, 3, 4],
    "stock": {1: 500, 2: 497, 3: 354, 4: 223},
    "req": {1: 17, 2: 65, 3: 26, 4: 332},
    "cost": {
        (1, 2): 17, (1, 3): 3,  (1, 4): 5,
        (2, 1): 39, (2, 3): 18, (2, 4): 50,
        (3, 1): 8,  (3, 2): 45, (3, 4): 15,
        (4, 1): 11, (4, 2): 4,  (4, 3): 29,
    },
    "big_m": 10 ** 6,
}


def build_model(data=None):
    d = data or DATA
    W = list(d["warehouses"])
    arcs = list(d["cost"].keys())
    max_flow = max(d["stock"].values())

    model = pyo.ConcreteModel()
    model.nodes = pyo.Set(initialize=W)
    model.arcs = pyo.Set(initialize=arcs, dimen=2)
    model.out_arcs = pyo.Set(
        model.nodes, initialize={i: [(i, j) for j in W if (i, j) in arcs] for i in W}
    )
    model.in_arcs = pyo.Set(
        model.nodes, initialize={j: [(i, j) for i in W if (i, j) in arcs] for j in W}
    )

    model.x = pyo.Var(
        model.arcs, domain=pyo.NonNegativeReals,
        bounds=lambda m, i, j: (0, max_flow),
    )

    def obj_rule(m):
        return sum(d["cost"][(i, j)] * m.x[i, j] for (i, j) in arcs)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    def balance_rule(m, k):
        inflow = sum(m.x[i, j] for (i, j) in m.in_arcs[k])
        outflow = sum(m.x[i, j] for (i, j) in m.out_arcs[k])
        return d["stock"][k] + inflow - outflow >= d["req"][k]

    model.balance = pyo.Constraint(model.nodes, rule=balance_rule)

    return model


