import pyomo.environ as pyo

DATA = {
    "warehouses": [1, 2, 3, 4],
    "initial": {1: 500, 2: 497, 3: 354, 4: 223},
    "need": {1: 17, 2: 65, 3: 26, 4: 332},
    "cost": {
        (1, 2): 17, (1, 3): 3,  (1, 4): 5,
        (2, 1): 39, (2, 3): 18, (2, 4): 50,
        (3, 1): 8,  (3, 2): 45, (3, 4): 15,
        (4, 1): 11, (4, 2): 4,  (4, 3): 29,
    },
}


def build_model(data=None):
    d = data or DATA

    model = pyo.ConcreteModel()

    model.I = pyo.Set(initialize=d["warehouses"], ordered=True)

    def _arc_init(m):
        return [(i, j) for i in m.I for j in m.I if i != j]

    model.arcs = pyo.Set(initialize=_arc_init, dimen=2)

    model.ship = pyo.Var(model.arcs, within=pyo.NonNegativeReals)

    def obj_rule(m):
        return sum(d["cost"][(i, j)] * m.ship[i, j] for (i, j) in m.arcs)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    def balance_rule(m, i):
        outflow = sum(m.ship[i, j] for j in m.I if (i, j) in m.arcs)
        inflow = sum(m.ship[j, i] for j in m.I if (j, i) in m.arcs)
        return d["initial"][i] - outflow + inflow == d["need"][i]

    model.balance = pyo.Constraint(model.I, rule=balance_rule)

    return model


